-- Migration 0001 — users table for auth and admin.
-- SQLite port of the old Postgres schema:
--   id          TEXT holding a v4 UUID generated by the app (crypto.randomUUID), since SQLite has no uuid type
--   is_admin    INTEGER 0/1, since SQLite has no boolean type
--   timestamps  ISO-8601 UTC text with milliseconds, so they parse straight into JS Dates
-- updated_at is set explicitly by every UPDATE in the query layer rather than by a trigger,
-- because RETURNING does not see values an AFTER trigger writes.

CREATE TABLE users (
    id            TEXT    PRIMARY KEY NOT NULL,
    name          TEXT,
    username      TEXT    NOT NULL UNIQUE,
    email         TEXT    NOT NULL UNIQUE,
    password_hash TEXT    NOT NULL,
    is_admin      INTEGER NOT NULL DEFAULT 0 CHECK (is_admin IN (0, 1)),
    created_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
